function glyph(name,size=20){
 const paths={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1Z"/><path d="M9 21v-8h6v8"/>',book:'<path d="M12 5v16M3 4h6l3 2 3-2h6v16h-6l-3 2-3-2H3Z"/>',check:'<path d="m5 12 4 4L19 6"/>',tasks:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="m7 9 2 2 3-3M14 9h3M7 16h10"/>',chart:'<path d="M4 3v17h17M8 15v-4M13 15V6M18 15v-7"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',camera:'<path d="M8 5 9 3h6l1 2h4a1 1 0 0 1 1 1v13a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V6a1 1 0 0 1 1-1Z"/><circle cx="12" cy="12" r="4"/>',plus:'<path d="M12 4v16M4 12h16"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',receipt:'<path d="M5 3h14v18l-3-2-4 2-4-2-3 2ZM8 7h8M8 11h8M8 15h5"/>',water:'<path d="M12 3S5 11 5 15a7 7 0 0 0 14 0c0-4-7-12-7-12Z"/>',electric:'<path d="m14 2-9 12h7l-2 8 9-12h-7Z"/>',gas:'<path d="M12 3c3 5 6 7 6 12a6 6 0 0 1-12 0c0-3 2-6 3-8 0 3 1 4 2 5 1-3 2-5 1-9Z"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',bell:'<path d="M5 17h14l-2-3V9a5 5 0 0 0-10 0v5ZM10 21h4"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5ZM20 2v4m-2-2h4"/>'};
 return `<svg class="ui-icon" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.receipt}</svg>`;
}

const state={page:'home',scope:'personal',origin:'all',taskTab:'tasks',period:'month',basis:'net',search:'',category:'',trash:false,archived:false,manager:true,managerName:'林然',usedRecognition:0,usedAnalysis:0,analyses:[],shares:[],nextId:100};
